import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"03 - Login And Broker Flow","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/api-layer.md","filePath":"developers/design-documentation/api-layer.md"}'),r={name:"developers/design-documentation/api-layer.md"};function i(n,e,d,l,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="_03-login-and-broker-flow" tabindex="-1">03 - Login And Broker Flow <a class="header-anchor" href="#_03-login-and-broker-flow" aria-label="Permalink to &quot;03 - Login And Broker Flow&quot;">​</a></h1><h2 id="two-authentication-layers" tabindex="-1">Two Authentication Layers <a class="header-anchor" href="#two-authentication-layers" aria-label="Permalink to &quot;Two Authentication Layers&quot;">​</a></h2><p>Tradeboard separates the local application session from the broker session.</p><ol><li>The user authenticates to the self-hosted app with username/password and optional TOTP.</li><li>The user selects a broker and completes that broker&#39;s auth flow, or resumes an existing valid broker token.</li><li>External <code>/api/v1</code> clients use the Tradeboard API key, which resolves the active broker token server-side.</li></ol><p>A broker token can expire while the app cookie remains valid. In that state the UI must offer broker reconnect rather than hard-logging the user out.</p><h2 id="app-login" tabindex="-1">App Login <a class="header-anchor" href="#app-login" aria-label="Permalink to &quot;App Login&quot;">​</a></h2><p><code>blueprints/auth.py</code> owns setup, password login, TOTP promotion, session status, password changes, and logout. Successful login can resume an existing broker session through <code>_try_resume_broker_session</code>; otherwise it sends the user to broker selection.</p><p>When login TOTP is required, the password step stores a short-lived <code>pending_totp_user</code> rather than establishing <code>session[&quot;user&quot;]</code>. A correct <code>/auth/login/totp</code> request promotes it to an authenticated session and records <code>totp_verified_at</code> for sensitive downstream authorization such as Remote MCP write consent.</p><h2 id="broker-discovery-and-auth" tabindex="-1">Broker Discovery And Auth <a class="header-anchor" href="#broker-discovery-and-auth" aria-label="Permalink to &quot;Broker Discovery And Auth&quot;">​</a></h2><p><code>utils/plugin_loader.py</code> reads <code>broker/*/plugin.json</code> and lazy-loads <code>broker.&lt;key&gt;.api.auth_api</code>. Generic callbacks are handled by <code>blueprints/brlogin.py</code>; specialized routes support brokers that need extra OTP, TOTP, or credential steps.</p><p>The current plugin inventory is 36: 34 securities brokers, Delta Exchange for crypto derivatives, and a Dhan sandbox plugin for paper trading. Authentication shape varies by broker, and capability metadata is the correct way for UI code to discover supported exchanges and features.</p><h2 id="token-storage" tabindex="-1">Token Storage <a class="header-anchor" href="#token-storage" aria-label="Permalink to &quot;Token Storage&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Data</th><th>Storage behavior</th></tr></thead><tbody><tr><td>Password</td><td>Argon2 hash in the user database</td></tr><tr><td>Tradeboard API key</td><td>Argon2+pepper verification hash and encrypted retrievable value</td></tr><tr><td>Broker auth/feed tokens</td><td>Fernet ciphertext derived from installation secrets</td></tr><tr><td>TOTP secret</td><td>Encrypted at rest</td></tr><tr><td>Browser session</td><td>Signed Flask session cookie with host-dependent secure flags</td></tr></tbody></table><p><code>upsert_auth()</code> compares decrypted old and new broker/feed tokens. Fernet encryption is nondeterministic, so ciphertext comparison would be wrong. If the token, feed token, broker, and revoke state are unchanged, a resumed login does not tear down the shared broker WebSocket feed.</p><h2 id="multi-session-model" tabindex="-1">Multi-Session Model <a class="header-anchor" href="#multi-session-model" aria-label="Permalink to &quot;Multi-Session Model&quot;">​</a></h2><p>Tradeboard allows up to five active app sessions for the single configured user. A new row replaces an existing row for the same username and IP; at the cap, the oldest row is removed. Every device shares the installation&#39;s one active broker session and server-side market-data feed.</p><p>The SPA polls <code>/auth/session-status</code>. That route refreshes the current <code>active_sessions.last_seen</code> at most once every 30 seconds and reports the current active-session count.</p><h2 id="broker-expiry-and-reconnect" tabindex="-1">Broker Expiry And Reconnect <a class="header-anchor" href="#broker-expiry-and-reconnect" aria-label="Permalink to &quot;Broker Expiry And Reconnect&quot;">​</a></h2><p>If session status finds a valid app session but no active broker token, it returns:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;status&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;authenticated&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;logged_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;broker_session_expired&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>It intentionally preserves the app session. Protected dashboard APIs can then return the broker-expired state and the frontend can route the user through <code>/auth/broker</code> again.</p><h2 id="revocation-events" tabindex="-1">Revocation Events <a class="header-anchor" href="#revocation-events" aria-label="Permalink to &quot;Revocation Events&quot;">​</a></h2><ul><li>Explicit logout removes the device session and clears the browser session.</li><li>Daily session-expiry handling revokes broker access according to configuration.</li><li>Password change clears every active app session, emits <code>force_logout</code>, and clears the current cookie.</li><li>Unchanged multi-device broker resume preserves the shared feed.</li></ul><p>See <a href="./40-logout-and-session-expiry">40 Logout And Session Lifecycle</a> for the expiry and heartbeat state machine.</p><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>blueprints/auth.py</code></td><td>App login, TOTP, session APIs, logout</td></tr><tr><td><code>blueprints/brlogin.py</code></td><td>Broker callbacks and special login helpers</td></tr><tr><td><code>blueprints/broker_credentials.py</code></td><td>Credential and capability APIs</td></tr><tr><td><code>database/auth_db.py</code></td><td>Broker tokens, API keys, active sessions, login audit</td></tr><tr><td><code>utils/plugin_loader.py</code></td><td>Plugin discovery and lazy auth loading</td></tr><tr><td><code>utils/session.py</code></td><td>Protected-route session validity</td></tr><tr><td><code>frontend/src/components/auth/AuthSync.tsx</code></td><td>Backend-to-Zustand session synchronization</td></tr></tbody></table>`,26)])])}const k=t(r,[["render",i]]);export{u as __pageData,k as default};
